from tornado.process import fork_processes


class TestForkProcesses:
    @patch("tornado.process.sys.platform", "win32")
    def test_fork_processes_windows_raises_exception(self):
        """Test that fork_processes raises an exception on Windows."""
        with pytest.raises(Exception, match="fork not available on windows"):
            fork_processes(1)

    @patch("tornado.process.sys.platform", "linux")
    @patch("tornado.process.cpu_count", return_value=4)
    @patch("tornado.process.os.fork", return_value=12345)  # Simulate parent process
    @patch("tornado.process.os.wait")
    @patch("tornado.process.sys.exit")
    def test_fork_processes_with_none_num_processes(
        self, mock_exit, mock_wait, mock_fork, mock_cpu_count
    ):
        """Test fork_processes with num_processes=None."""
        mock_wait.return_value = (12345, 0)  # Simulate normal child exit
        fork_processes(None)
        mock_cpu_count.assert_called_once()
        assert mock_fork.call_count == 4
        mock_exit.assert_called_once_with(0)

    @patch("tornado.process.sys.platform", "linux")
    @patch("tornado.process.os.fork", side_effect=[1001, 1002, 0, 1003])  # Third call simulates child
    @patch("tornado.process._reseed_random")
    def test_fork_processes_returns_task_id_in_child(self, mock_reseed, mock_fork):
        """Test that fork_processes returns task ID in child process."""
        result = fork_processes(3)
        assert result == 2  # Third fork returns 0 in child, so task id is 2
        assert mock_reseed.call_count == 1

    @patch("tornado.process.sys.platform", "linux")
    @patch("tornado.process.os.fork", return_value=1001)
    @patch("tornado.process.os.wait", return_value=(1001, 0))  # Normal exit
    @patch("tornado.process.sys.exit")
    def test_fork_processes_normal_child_exit(self, mock_exit, mock_wait, mock_fork):
        """Test fork_processes behavior when child exits normally."""
        with patch.dict(os.environ, {"TESTING": "1"}):
            fork_processes(1)
        mock_exit.assert_called_once_with(0)

    @patch("tornado.process.sys.platform", "linux")
    @patch("tornado.process.os.fork", return_value=1001)
    @patch("tornado.process.os.wait")
    @patch("tornado.process.sys.exit")
    def test_fork_processes_abnormal_child_exit_status(self, mock_exit, mock_wait, mock_fork):
        """Test fork_processes restarts child on non-zero exit status."""
        # First wait returns abnormal exit, second would restart but we limit max_restarts
        mock_wait.side_effect = [(1001, 1), (1001, 1)]  # Non-zero exit status
        with pytest.raises(RuntimeError, match="Too many child restarts, giving up"):
            fork_processes(1, max_restarts=1)
        # Should not reach sys.exit since exception is raised
        mock_exit.assert_not_called()

    @patch("tornado.process.sys.platform", "linux")
    @patch("tornado.process.os.fork", return_value=1001)
    @patch("tornado.process.os.wait")
    @patch("tornado.process.sys.exit")
    def test_fork_processes_child_killed_by_signal(self, mock_exit, mock_wait, mock_fork):
        """Test fork_processes restarts child killed by signal."""
        # Mock WIFSIGNALED to return True and WTERMSIG to return signal number
        with patch("tornado.process.os.WIFSIGNALED", return_value=True), \
             patch("tornado.process.os.WTERMSIG", return_value=9):
            # First wait returns signal termination, second would restart but we limit max_restarts
            mock_wait.side_effect = [(1001, 0), (1001, 0)]  # The values don't matter as WIFSIGNALED is mocked
            with pytest.raises(RuntimeError, match="Too many child restarts, giving up"):
                fork_processes(1, max_restarts=1)
        mock_exit.assert_not_called()

    @patch("tornado.process.sys.platform", "linux")
    @patch("tornado.process.os.fork", return_value=1001)
    @patch("tornado.process.os.wait")
    @patch("tornado.process.sys.exit")
    def test_fork_processes_unknown_pid_in_wait(self, mock_exit, mock_wait, mock_fork):
        """Test fork_processes ignores unknown PIDs from os.wait."""
        # First return unknown PID, second return known PID with normal exit
        mock_wait.side_effect = [(1002, 0), (1001, 0)]
        with patch("tornado.process.os.WIFSIGNALED", return_value=False), \
             patch("tornado.process.os.WEXITSTATUS", return_value=0):
            fork_processes(1)
        mock_exit.assert_called_once_with(0)

