import typing
import re
from unittest.mock import patch, MagicMock
from tornado.escape import make_link

class TestMakeLink:

    @patch('tornado.escape.permitted_protocols', ['http', 'https'])
    @patch('tornado.escape.require_protocol', False)
    @patch('tornado.escape.extra_params', '')
    @patch('tornado.escape.shorten', False)
    def test_valid_url_without_protocol(self):
        match = re.match(r'(.+?)(?:://)?(.+?)?(.*)', 'example.com')
        result = make_link(match)
        assert result == '<a href="http://example.com">example.com</a>'

    @patch('tornado.escape.permitted_protocols', ['http', 'https'])
    @patch('tornado.escape.require_protocol', True)
    @patch('tornado.escape.extra_params', '')
    @patch('tornado.escape.shorten', False)
    def test_url_without_protocol_when_required(self):
        match = re.match(r'(.+?)(?:://)?(.+?)?(.*)', 'example.com')
        result = make_link(match)
        assert result == 'example.com'

    @patch('tornado.escape.permitted_protocols', ['http', 'https'])
    @patch('tornado.escape.require_protocol', False)
    @patch('tornado.escape.extra_params', '')
    @patch('tornado.escape.shorten', False)
    def test_valid_url_with_http_protocol(self):
        match = re.match(r'(.+?)(?:://)?(.+?)?(.*)', 'http://example.com')
        result = make_link(match)
        assert result == '<a href="http://example.com">http://example.com</a>'

    @patch('tornado.escape.permitted_protocols', ['http', 'https'])
    @patch('tornado.escape.require_protocol', False)
    @patch('tornado.escape.extra_params', '')
    @patch('tornado.escape.shorten', False)
    def test_valid_url_with_https_protocol(self):
        match = re.match(r'(.+?)(?:://)?(.+?)?(.*)', 'https://example.com')
        result = make_link(match)
        assert result == '<a href="https://example.com">https://example.com</a>'

    @patch('tornado.escape.permitted_protocols', ['http', 'https'])
    @patch('tornado.escape.require_protocol', False)
    @patch('tornado.escape.extra_params', '')
    @patch('tornado.escape.shorten', False)
    def test_invalid_protocol(self):
        match = re.match(r'(.+?)(?:://)?(.+?)?(.*)', 'ftp://example.com')
        result = make_link(match)
        assert result == 'ftp://example.com'

    @patch('tornado.escape.permitted_protocols', ['http', 'https'])
    @patch('tornado.escape.require_protocol', False)
    @patch('tornado.escape.extra_params', ' target="_blank"')
    @patch('tornado.escape.shorten', False)
    def test_extra_params_string(self):
        match = re.match(r'(.+?)(?:://)?(.+?)?(.*)', 'http://example.com')
        result = make_link(match)
        assert result == '<a href="http://example.com" target="_blank">http://example.com</a>'

    @patch('tornado.escape.permitted_protocols', ['http', 'https'])
    @patch('tornado.escape.require_protocol', False)
    @patch('tornado.escape.shorten', False)
    def test_extra_params_callable(self):
        mock_callable = MagicMock(return_value='class="link"')
        with patch('tornado.escape.extra_params', mock_callable):
            match = re.match(r'(.+?)(?:://)?(.+?)?(.*)', 'http://example.com')
            result = make_link(match)
            assert result == '<a href="http://example.com" class="link">http://example.com</a>'
            mock_callable.assert_called_once_with('http://example.com')

    @patch('tornado.escape.permitted_protocols', ['http', 'https'])
    @patch('tornado.escape.require_protocol', False)
    @patch('tornado.escape.extra_params', '')
    @patch('tornado.escape.shorten', True)
    def test_shorten_long_url(self):
        long_url = 'http://example.com/very/long/path/with/lots/of/segments'
        match = re.match(r'(.+?)(?:://)?(.+?)?(.*)', long_url)
        result = make_link(match)
        assert '...' in result
        assert 'title="' in result

    @patch('tornado.escape.permitted_protocols', ['http', 'https'])
    @patch('tornado.escape.require_protocol', False)
    @patch('tornado.escape.extra_params', '')
    @patch('tornado.escape.shorten', True)
    def test_shorten_short_url(self):
        short_url = 'http://ex.com/p'
        match = re.match(r'(.+?)(?:://)?(.+?)?(.*)', short_url)
        result = make_link(match)
        assert '...' not in result
        assert short_url in result

    @patch('tornado.escape.permitted_protocols', ['http', 'https'])
    @patch('tornado.escape.require_protocol', False)
    @patch('tornado.escape.extra_params', '')
    @patch('tornado.escape.shorten', True)
    def test_shorten_url_avoid_html_entities(self):
        url_with_amp = 'http://example.com/path&param=value'
        match = re.match(r'(.+?)(?:://)?(.+?)?(.*)', url_with_amp)
        result = make_link(match)
        # Should handle ampersand correctly to avoid breaking HTML entities
        assert '<a href=' in result

